"""Football Shorts original imagegen identity, embedded for safe code-only updates."""
import base64
from pathlib import Path
PNG = ''
ICO = ''

def write_assets(directory):
    directory=Path(directory);directory.mkdir(parents=True,exist_ok=True)
    for name,data in [('FootballShorts.png',PNG),('FootballShorts.ico',ICO)]:
        (directory/name).write_bytes(base64.b64decode(data))
    return directory/'FootballShorts.ico'
